/// A reading's way to the level's word (`remember`).
const REMEMBERED: u16 = u16::MAX - 2;

#[allow(clippy::all, dead_code)]
impl<L: Layout> P<'_, L> {
    /// `relabel … inner G`: the node the node made last at this level, a wrap, holds first takes field `G`.
    fn relabel_inner(&mut self, field: u16) -> R {
        let at = *self.made.last().unwrap_or(&NONE);
        if at == NONE || self.w.size(at as usize) < 2 {
            return self.refuse();
        }
        let at = at as usize + 1;
        let k = self.w.key(at);
        self.w.set_key(at, k & !(0x3f << 10) | u32::from(field) << 10);
        Ok(())
    }

    /// `relabel F`: the node made last at this level takes field `F`.
    fn relabel_field(&mut self, field: u16) -> R {
        let at = *self.made.last().unwrap_or(&NONE);
        if at == NONE {
            return self.refuse();
        }
        let k = self.w.key(at as usize);
        self.w.set_key(at as usize, k & !(0x3f << 10) | u32::from(field) << 10);
        Ok(())
    }

    /// `relabel … as M`: the node made last at this level a `kind` now.
    fn relabel_kind(&mut self, kind: u16) -> R {
        let at = *self.made.last().unwrap_or(&NONE);
        if at == NONE {
            return self.refuse();
        }
        let k = self.w.key(at as usize);
        self.w.set_key(at as usize, k & !0x3ff | u32::from(kind));
        Ok(())
    }

    /// `drop`: the node made last at this level goes, the nodes inside it in its place; none is made last at this
    /// level until the next.
    ///
    /// As the machine's `drop` leaves its record of kind `DEAD` in the table (left out at `ACCEPT`), the node is held
    /// as dead in the node open (`dead`), so that a reading that reaches it refuses. A dead node in it goes to that
    /// node too.
    fn drop_made(&mut self) -> R {
        let at = *self.made.last().unwrap_or(&NONE);
        let open = *self.open.last().unwrap_or(&NONE);
        for o in &mut self.dead {
            if *o == at {
                *o = open;
            }
        }
        self.reread(Some(None), |_| None, |f| f)?;
        self.dead.push(open);
        self.set_made(NONE);
        Ok(())
    }

    /// The dead nodes (`drop`) in the node read again from `at` (`nodes`, as `reread` has them): one in a node the
    /// reading reaches, not one it keeps whole, refuses, as the machine's reading refuses the `DEAD` record it
    /// reaches (it names no such kind). Each other one is then in its node where the reading writes it.
    fn read_dead(&mut self, nodes: &[(u32, u32, u32, usize)], at: usize, root: Option<Option<u16>>, way: fn(u16) -> Option<Option<u16>>) -> R {
        let (mut to, mut reached) = (vec![NONE; nodes.len()], vec![false; nodes.len()]);
        let (mut next, mut kept) = (at as u32, 0);
        for (i, &(key, _, _, size)) in nodes.iter().enumerate() {
            let way = if i < kept || key >> 16 & 1 == 1 {
                None
            } else if i == 0 {
                match root {
                    Some(Some(u16::MAX)) => way((key & 0x3ff) as u16),
                    r => r,
                }
            } else {
                way((key & 0x3ff) as u16)
            };
            match way {
                None => kept = kept.max(i + size),
                Some(_) => reached[i] = true,
            }
            if way != Some(None) {
                to[i] = next;
                next += 1;
            }
        }
        for o in &mut self.dead {
            let j = (*o as usize).wrapping_sub(at);
            if j < nodes.len() {
                if reached[j] {
                    return self.refuse();
                }
                *o = to[j];
            }
        }
        Ok(())
    }
}

/// The tape of `src` from tier 1's records (each token's first and last bytes and code), finished by `finish` (the
/// image, or the columns, as the grammar's lean parser finishes), or the byte it was refused at.
pub fn parse<F: rerail_tape_format::Finish>(src: &[u8], lx: &crate::tier1::Lexed, finish: &mut F) -> Result<F::Out, u32> {
    // Where tier 1 sends the file to tree-sitter.
    if lx.refused {
        return Err(0);
    }
    let mut widths = Widths::guess(src.len());
    loop {
        // Nearly every file is parsed at the narrow widths, fixed in the parser's code, as the lean parser's.
        let at = if widths == Narrow::WIDTHS { parse_at(src, lx, Narrow, finish)? } else { parse_at(src, lx, widths, finish)? };
        match at {
            Ok(c) => return Ok(c),
            Err(rerail_tape_format::Redo(w)) => {
                if w == widths {
                    return Err(u32::MAX);
                }
                widths = w;
            }
        }
    }
}

/// `parse` at `layout`'s widths: the tape `finish` makes of the writer, or the widths to parse at again; or the byte
/// it was refused at.
fn parse_at<L: Layout, F: rerail_tape_format::Finish>(src: &[u8], lx: &crate::tier1::Lexed, layout: L, finish: &mut F) -> R<Result<F::Out, rerail_tape_format::Redo>> {
    let mut p = P::new(src, lx, layout)?;
    p.run()?;
    Ok(finish.finish(p.w))
}
